#!/usr/bin/env bash
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing H2H fixes (budget-forced vanilla + standard prompt + requeue)..."
decode "scripts/ntc_h2h_table.py" << 'B64EOF'

B64EOF
decode "apply_prompt_patch.py" << 'B64EOF'

B64EOF
decode "run_queue_h2h2.sh" << 'B64EOF'

B64EOF
python apply_prompt_patch.py && rm apply_prompt_patch.py
chmod +x run_queue_h2h2.sh
echo ""
echo "Installed. Steps:"
echo "  1) instant: re-run table with budget-forced vanilla"
echo "  2) bash run_queue_h2h2.sh --dry && bash run_queue_h2h2.sh"